def assign_category(recipes: List[Set[str]], categories: Dict[str, Set[str]]) -> List[str]:
    result = []

    for recipe in recipes:
        best_category = ""
        max_subs = 0

        for category, sub_ingredients in categories.items():
            if sub_ingredients.issubset(recipe) and len(sub_ingredients) > max_subs:
                best_category = category
                max_subs = len(sub_ingredients)

        result.append(best_category)

    return result

